const body = $input.item.json.body ?? $input.item.json;
const { event, repository, commit_sha, author, message, environment, system } = body;

const safeEvent  = event      || 'unknown';
const safeRepo   = repository || 'unknown';
const safeSha    = (commit_sha || '').slice(0, 7) || 'n/a';
const safeAuthor = author     || 'unknown';
const safeMsg    = message    || '(no message)';
const safeEnv    = environment || 'production';
const safeSystem = system     || 'NOIZY.ai Core';

// Route to different Discord embed styles by event type
let emoji, label;
if (safeEvent === 'release') {
  emoji = '🚀';
  label = 'Release Published';
} else if (safeEvent === 'push') {
  emoji = '📦';
  label = 'Push to Main';
} else {
  emoji = '⚙️';
  label = 'Workflow Dispatch';
}

return {
  json: {
    emoji,
    label,
    event:      safeEvent,
    repository: safeRepo,
    commit_sha: safeSha,
    author:     safeAuthor,
    message:    safeMsg,
    environment: safeEnv,
    system:     safeSystem,
    ts_iso:     new Date().toISOString()
  }
};
